import{_ as a,c as t,a3 as r,o}from"./chunks/framework.C-yY9WsR.js";const g=JSON.parse('{"title":"在线部署","description":"","frontmatter":{},"headers":[],"relativePath":"guide/在线部署.md","filePath":"guide/在线部署.md"}'),p={name:"guide/在线部署.md"};function c(i,e,d,n,s,l){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="在线部署" tabindex="-1">在线部署 <a class="header-anchor" href="#在线部署" aria-label="Permalink to &quot;在线部署&quot;">​</a></h1><p>以下平台部署的都是网页管理面板, 与 <a href="/guide/面板模式部署">面板模式部署</a> 一致.</p><p>这些免费平台不提供持久磁盘, 容器重新部署后本地文件会丢失. 请同时准备一个 MongoDB (例如 <a href="https://www.mongodb.com/products/platform/atlas-database" target="_blank" rel="noreferrer">MongoDB Atlas</a> 免费层), 并设置环境变量 <code>EK_MONGODB</code> 为连接字符串, 否则每次重新部署都需要重新添加账号、重新登录. 具体说明见 <a href="/guide/面板模式部署#用-mongodb-无持久化部署">用 MongoDB 无持久化部署</a>.</p><h2 id="huggingface-space" tabindex="-1">Huggingface Space <a class="header-anchor" href="#huggingface-space" aria-label="Permalink to &quot;Huggingface Space&quot;">​</a></h2><p>Embykeeper 可以通过免费的 Huggingface Space 托管平台进行部署, 点击下方按钮开始部署:</p><div style="display:flex;justify-content:flex-start;align-items:center;"><a href="https://huggingface.co/spaces/ekuser/ek?duplicate=true"><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/deploy-to-hf.svg" alt="Deploy to Huggingface Space"></a><a href="https://blog.zetx.tech/2024/05/19/embykeeper-hf-tutorial/" style="margin-left:10px;"><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/hf-tutorial.svg" alt="Tutorial"></a></div><p>复制 Space 后, 在 Space 的 Settings 中添加两个 Secrets: <code>EK_WEBPASS</code> (登录密码) 与 <code>EK_MONGODB</code> (数据库连接字符串), 然后重启 Space.</p><p>Space 使用仓库中的 <code>hf/Dockerfile</code> 构建, 已按 Huggingface 的运行方式适配: 面板监听 Space README 里 <code>app_port</code> 声明的 <code>1818</code> 端口, 数据放在 <code>/data</code> 目录 (Huggingface 以 UID 1000 运行容器, 该目录已授权可写). 镜像更新或修改 Secrets 后如果 Space 一直显示启动中, 在 Settings 里执行一次 Factory reboot 即可.</p><p>请注意 Huggingface Space 的 Web 服务不活跃 48 小时将自动停止, 因此必须部署云监控以持续激活.</p><p><strong>注意</strong>: 使用云监控使得 Huggingface Space 的 Web 服务保持运行是违反 Huggingface Space TOS 的行为, 您应预见可能的不稳定或封号. 如有可能请使用 Huggingface Space 小号, 或选择其他部署方式.</p><h2 id="koyeb" tabindex="-1">Koyeb <a class="header-anchor" href="#koyeb" aria-label="Permalink to &quot;Koyeb&quot;">​</a></h2><p>Embykeeper 可以通过免费的 Koyeb 托管平台进行部署, 点击下方按钮开始部署:</p><div style="display:flex;justify-content:flex-start;align-items:center;"><a href="https://app.koyeb.com/deploy?repository=github.com/emby-keeper/emby-keeper&amp;branch=stable&amp;type=git&amp;name=embykeeper&amp;builder=dockerfile&amp;dockerfile=deploy%2Fcloud%2FDockerfile&amp;ports=8000;http;/&amp;env[EK_WEBPASS]=&amp;env[EK_MONGODB]="><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/deploy-to-koyeb.svg" alt="Deploy to Koyeb"></a><a href="https://blog.zetx.tech/2025/01/14/embykeeper-koyeb-tutorial" style="margin-left:10px;"><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/koyeb-tutorial.svg" alt="Tutorial"></a></div><p>创建应用时填写 <code>EK_WEBPASS</code> (登录密码) 与 <code>EK_MONGODB</code> (数据库连接字符串), 端口保持 <code>8000</code> (HTTP).</p><h2 id="render-com" tabindex="-1">Render.com <a class="header-anchor" href="#render-com" aria-label="Permalink to &quot;Render.com&quot;">​</a></h2><p>Embykeeper 可以通过免费的 Render 托管平台进行部署, 点击下方按钮开始部署:</p><div style="display:flex;justify-content:flex-start;align-items:center;"><a href="https://render.com/deploy?repo=https://github.com/emby-keeper/emby-keeper/tree/stable"><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/deploy-to-render.svg" alt="Deploy to Render"></a><a href="https://blog.zetx.tech/2023/06/26/embykeeper-render-tutorial" style="margin-left:10px;"><img src="https://github.com/emby-keeper/emby-keeper/raw/main/images/render-tutorial.svg" alt="Tutorial"></a></div><p>Blueprint 会读取仓库中的 <code>render.yaml</code>. 部署完成后在服务的 Environment 中填写 <code>EK_WEBPASS</code> (登录密码) 与 <code>EK_MONGODB</code> (数据库连接字符串), 然后重新部署.</p><p>请注意 Render.com 的 Web 服务不活跃 15 分钟将自动停止, 因此必须部署云监控以持续激活.</p><p><strong>注意</strong>: 使用云监控使得 Render.com 的 Web 服务保持运行是违反 Render.com TOS 的行为, 您应预见可能的不稳定或封号. 如有可能请使用 Render.com 小号, 或选择其他部署方式.</p><h2 id="其他免费-paas" tabindex="-1">其他免费 PaaS <a class="header-anchor" href="#其他免费-paas" aria-label="Permalink to &quot;其他免费 PaaS&quot;">​</a></h2><p>您也可以通过 <a href="https://app.patr.cloud/" target="_blank" rel="noreferrer">Patr.cloud</a> (<a href="https://zetx.tech/2023/06/26/embykeeper-patr-tutorial/" target="_blank" rel="noreferrer">教程</a>) 等平台进行部署.</p><p>镜像 <code>embykeeper/embykeeper</code> 默认启动网页面板, 监听 <code>8000</code> 端口. 平台若提供持久磁盘, 挂载到 <code>/app</code> 即可用文件模式; 否则请设置 <code>EK_MONGODB</code>.</p><h2 id="在自己的服务器使用-docker-compose-部署" tabindex="-1">在自己的服务器使用 Docker Compose 部署 <a class="header-anchor" href="#在自己的服务器使用-docker-compose-部署" aria-label="Permalink to &quot;在自己的服务器使用 Docker Compose 部署&quot;">​</a></h2><ul><li><a href="/guide/面板模式部署">🖥️ 面板模式部署</a> <strong>(推荐, 自带图形界面)</strong></li><li><a href="/guide/Linux-Docker-Compose-部署#部署在线控制台-旧版">旧版在线控制台</a></li></ul>',25)]))}const h=a(p,[["render",c]]);export{g as __pageData,h as default};
